"""Finite rings generated by the queue handback rule.

A consumption is carried directly by its queue/controller, or by one already
required publication returning to the producer queue. This is a bounded rule
with checked premises; no arbitrary paths, execution graphs or post-selection
progress search participate. Window membership describes parametric uses,
including outer reentry. A finite upper bound can instead give one ID per use.
"""

from dataclasses import dataclass

from ..diagnostics import CompileError, ErrorKind, require
from ..scalar import expression, literal, substitute
from .event_contracts import CROSS_BACKLOG, LOCAL_CAPACITY, CaseLease, StructuredEventLease
from .guard_cover import opposite, prove_guard_cover
from .structured_protocols import NotificationKind
from .structured_schedule import ActionGuard, Comparison


@dataclass(frozen=True, slots=True)
class Handback:
    consume: object
    next_set: object
    # None is direct queue/controller consumption. A relay is always an
    # actual, already-required notification, never a generated barrier.
    relay: object | None
    publication: object | None
    acquisition: object | None
    condition: ActionGuard


@dataclass(frozen=True, slots=True)
class Reuse:
    loop: object | None
    delta: int
    upper_uses: int | None
    condition: ActionGuard
    handbacks: tuple[Handback, ...] = ()


class HandbackRule:
    def __init__(self, domains, *, boundaries=()):
        self.domains = domains
        self.peers = tuple(
            n for n in domains.notifications if n.mechanism is not NotificationKind.PIPE_FENCE
        )
        self.at_native = {}
        self.at_queue = {}
        self.boundary_cases = dict(boundaries)
        self.declined_boundaries = {}
        for peer in self.peers:
            for source in peer.sources:
                self.at_native.setdefault((source.operation, source.actor), []).append(
                    (peer, source)
                )
                site = domains.dispatch.site(source)
                self.at_queue.setdefault(
                    (site.scope, site.stage, source.actor, peer.source_engine), []
                ).append((peer, source))

    def _eligible(self, old_channel, old, target_channel, target, peer):
        return (
            any(old.actor is p.actor for p in peer.sources)
            and (
                self.domains._gate(old_channel)
                or old_channel.destination_engine is peer.source_engine
            )
            and any(target.actor is p.actor for p in peer.consumers)
            and (
                self.domains._gate(peer) or peer.destination_engine is target_channel.source_engine
            )
        )

    def _cases(self, peer):
        cases = self.domains.cases[peer]
        if self.domains.clocks[peer] and not any(c.windows for c in cases):
            if peer not in self.boundary_cases:
                from .event_families import build_event_family

                # Cell credits need no dense ordinal. A streaming caller can
                # additionally require exact invocation boundary membership.
                # Universal pairing survives this domain specialization.
                try:
                    cases = build_event_family(self.domains, peer)
                except CompileError as error:
                    if error.kind is not ErrorKind.UNSUPPORTED or error.phase not in {
                        "event-parameter-cases",
                        "event-window-membership",
                    }:
                        raise
                    # This is optional relay precision, not the peer's own
                    # pairing/lifetime. An unavailable exact child boundary
                    # supplies no handback. Required channels are never
                    # removed and must still acquire a complete lease.
                    self.declined_boundaries[peer] = error
                    self.domains.work.optional_relay_declines += 1
                    cases = ()
                self.boundary_cases[peer] = cases
            return self.boundary_cases[peer]
        return cases

    def _step(self, bound, loop):
        d = self.domains
        task = d.dispatch.site(bound)
        scope, stage = task.scope, task.stage
        while scope.operation is not loop and scope.parent is not None:
            stage, scope = scope.parent_stage, scope.parent
        if scope.operation is not loop:
            return None
        coordinate = dict(bound.coordinates).get(loop)
        if coordinate is None:
            return None
        return d.arithmetic.normalize(
            expression(
                "sub", expression("add", coordinate, literal(stage)), d.control.loops[loop].ordinal
            )
        ).constant

    def candidates(self, peers, loop, delta, *, reentry, old, target):
        d = self.domains
        # Pairing already maps both ends of a channel. At an actual native
        # admission, bind a returning publication directly to that same
        # occurrence. No FIRST/LAST member or child-existence projection is
        # needed to identify a native we already have in hand.
        actual = {d.control.loops[l].ordinal: value for l, value in old.coordinates}
        for peer in peers:
            for source in peer.sources:
                if source.operation is not old.operation or source.actor is not old.actor:
                    continue
                bindings = {
                    ordinal: substitute(source.expression(ordinal), actual) for ordinal in actual
                }
                for case in d.cases[peer]:
                    if case.empty:
                        continue
                    sources = tuple(d._instance(p, bindings, case=case) for p in peer.sources)
                    consumers = tuple(d._instance(p, bindings, case=case) for p in peer.consumers)
                    anchor = d._instance(source, bindings, case=case)
                    matches = tuple(
                        Comparison(value, "==", dict(anchor.coordinates)[l])
                        for l, value in old.coordinates
                        if l in dict(anchor.coordinates)
                    )
                    # Retain these correspondence premises on the candidate;
                    # the handback must cover them under the caller's actual
                    # reuse domain, rather than assuming equality.
                    from dataclasses import replace

                    sources = tuple(
                        replace(p, guard=ActionGuard(p.guard.comparisons + matches))
                        for p in sources
                    )
                    yield peer, sources, consumers
        if loop is None:
            for peer in peers:
                for case in self._cases(peer):
                    if not case.empty:
                        for sources, consumers in d._instances(peer, case, None, 0):
                            yield peer, sources, consumers
            return
        begin, end = self._step(old, loop), self._step(target, loop)
        for peer in peers:
            starts = [self._step(p, loop) for p in peer.sources]
            stops = [self._step(p, loop) for p in peer.consumers]
            repeated = loop in d.clocks[peer]
            if repeated and any(s is None for s in starts + stops):
                continue
            if repeated and begin is not None and end is not None:
                offsets = range(begin - max(starts), end - min(stops) + 1)
            elif repeated:
                # Non-unit selected/reentry coordinates cannot supply a
                # constant finite handback horizon under this rule.
                continue
            else:
                offsets = (0,)
            for case in self._cases(peer):
                if case.empty:
                    continue
                for offset in offsets:
                    yield from (
                        (peer, sources, consumers)
                        for sources, consumers in d._instances(peer, case, loop, offset)
                    )

    def establish(
        self,
        channel,
        old,
        target_channel,
        target,
        assumptions,
        *,
        loop,
        delta,
        reentry,
        queue_composition=True,
        max_relays=2,
    ):
        require(max_relays in (1, 2), "handback rule supports one or two required relays")
        d = self.domains
        # This reuse domain already assumes both actual endpoints execute.
        # Their dominating load contracts survive activation simplification,
        # remain specific to their SID/generation, and provide no completion
        # edge or premise for an optional relay that has not yet executed.
        assumptions = tuple(
            dict.fromkeys(assumptions + d._input_ranges(old) + d._input_ranges(target))
        )
        conditions, handbacks = [], []

        def add(guard, relay=None, source=None, wait=None):
            remaining = []
            for test in guard.comparisons:
                premises = assumptions + tuple(remaining)
                if d.arithmetic.prove(test, premises):
                    continue
                if d.arithmetic.prove(opposite(test), premises):
                    return
                remaining.append(test)
            guard = ActionGuard(tuple(dict.fromkeys(remaining)))
            if guard in conditions:
                return
            conditions.append(guard)
            handbacks.append(Handback(old, target, relay, source, wait, guard))

        def covered():
            return prove_guard_cover(d.arithmetic, assumptions, tuple(conditions)) is not None

        for condition in d._following_conditions(channel, old, target_channel, target):
            add(condition)
        if covered():
            return tuple(handbacks)
        peers = tuple(
            p
            for p in self.peers
            if p is not channel and self._eligible(channel, old, target_channel, target, p)
        )
        # A consume before native admission can return on that native's
        # already-required publication. Try this local rule first: it has
        # the exact issue-site correspondence, without accumulating guards
        # from unrelated queue handoffs in the containing kernel.
        peers = tuple(
            sorted(
                peers,
                key=lambda p: (
                    not any(
                        s.operation is old.operation and s.actor is old.actor for s in p.sources
                    )
                ),
            )
        )
        for peer, sources, consumers in self.candidates(
            peers, loop, delta, reentry=reentry, old=old, target=target
        ):
            d.work.handback_candidates += 1
            active = tuple(
                dict.fromkeys(t for p in sources + consumers for t in p.guard.comparisons)
            )
            for source in sources:
                first = d._following_conditions(channel, old, peer, source)
                if not first:
                    continue
                for wait in consumers:
                    last = d._following_conditions(peer, wait, target_channel, target)
                    for a in first:
                        for b in last:
                            guard = ActionGuard(
                                tuple(dict.fromkeys(active + a.comparisons + b.comparisons))
                            )
                            add(guard, peer, source, wait)
            if covered():
                return tuple(handbacks)
        if max_relays == 1:
            return None
        # Compose two required handoffs through one actual intermediate queue.
        # Publications at the same native remain the narrowest case. A later
        # publication in the same stage/queue can also carry the consumption,
        # but only with its own checked queue order and occurrence binding.
        # This is a bounded two-handoff rule, not arbitrary path search.
        first_peers = tuple(
            p
            for p in self.peers
            if p is not channel
            and any(old.actor is s.actor for s in p.sources)
            and (d._gate(channel) or channel.destination_engine is p.source_engine)
        )
        for peer, sources, consumers in self.candidates(
            first_peers, loop, delta, reentry=reentry, old=old, target=target
        ):
            for middle in consumers:
                site = d.dispatch.site(middle)
                seconds = dict.fromkeys(
                    (
                        *self.at_native.get((middle.operation, middle.actor), ()),
                        *(
                            self.at_queue.get(
                                (site.scope, site.stage, middle.actor, peer.destination_engine), ()
                            )
                            if queue_composition
                            else ()
                        ),
                    )
                )
                for second, second_source in seconds:
                    if (
                        second in (channel, peer)
                        or not any(target.actor is w.actor for w in second.consumers)
                        or not (
                            d._gate(second)
                            or second.destination_engine is target_channel.source_engine
                        )
                    ):
                        continue
                    actual = {d.control.loops[l].ordinal: v for l, v in middle.coordinates}
                    bindings = {
                        ordinal: substitute(second_source.expression(ordinal), actual)
                        for ordinal in actual
                    }
                    for case in d.cases[second]:
                        if case.empty:
                            continue
                        d.work.handback_compositions += 1
                        ss = d._instance(second_source, bindings, case=case)
                        via = d._following_conditions(peer, middle, second, ss)
                        if not via:
                            continue
                        match = tuple(
                            Comparison(v, "==", dict(ss.coordinates)[l])
                            for l, v in middle.coordinates
                            if l in dict(ss.coordinates)
                        )
                        active = (
                            tuple(
                                t for p in sources + consumers + (ss,) for t in p.guard.comparisons
                            )
                            + match
                        )
                        for source in sources:
                            first = d._following_conditions(channel, old, peer, source)
                            for wait in (
                                d._instance(p, bindings, case=case) for p in second.consumers
                            ):
                                last = d._following_conditions(second, wait, target_channel, target)
                                for a in first:
                                    for middle_order in via:
                                        for b in last:
                                            guard = ActionGuard(
                                                tuple(
                                                    dict.fromkeys(
                                                        active
                                                        + wait.guard.comparisons
                                                        + a.comparisons
                                                        + middle_order.comparisons
                                                        + b.comparisons
                                                    )
                                                )
                                            )
                                            add(guard, (peer, second), (source, ss), (middle, wait))
                        if covered():
                            return tuple(handbacks)
        return None

    def reuse(self, channel, case, window, width, *, reentry, queue_composition=True):
        d, loop = self.domains, window.loop
        ordinal = d.control.loops[loop].ordinal
        result = []
        for phase, delta in window.reuse_phases(width):
            if reentry:
                old_sources, old_waits = list(d._instances(channel, case, loop, 0))[-1]
                next_sources, next_waits = next(d._instances(channel, case, loop, delta))
            else:
                shifted = {ordinal: expression("add", ordinal, literal(delta))}
                old_sources = tuple(d._instance(p, {}, case=case) for p in channel.sources)
                old_waits = tuple(d._instance(p, {}, case=case) for p in channel.consumers)
                next_sources = tuple(d._instance(p, shifted, case=case) for p in channel.sources)
                next_waits = tuple(d._instance(p, shifted, case=case) for p in channel.consumers)
            condition = ActionGuard(
                tuple(dict.fromkeys(case.condition.comparisons + phase.comparisons))
            )
            assumptions = tuple(
                dict.fromkeys(
                    condition.comparisons
                    + tuple(
                        t
                        for p in old_sources + old_waits + next_sources + next_waits
                        for t in p.guard.comparisons
                    )
                )
            )
            handbacks = []
            for old in old_waits:
                for target in next_sources:
                    rule = self.establish(
                        channel,
                        old,
                        channel,
                        target,
                        assumptions,
                        loop=loop,
                        delta=delta,
                        reentry=reentry,
                        queue_composition=queue_composition,
                    )
                    if rule is None:
                        return None
                    handbacks.extend(rule)
            result.append(Reuse(loop, delta, None, condition, tuple(handbacks)))
        return tuple(result)

    def _uses(self, channel, case, window, width, *, reentry, queue_composition):
        if window.upper is not None and window.upper <= width:
            return (Reuse(window.loop, 0, window.upper, case.condition),)
        return self.reuse(
            channel,
            case,
            window,
            width,
            reentry=reentry,
            queue_composition=queue_composition,
        )

    @staticmethod
    def _case_lease(case, rings, uses, *, cross, policy):
        width, ordinal = 1, literal(0)
        for window, ring in rings:
            width *= ring
            local = (
                literal(0)
                if window.single or ring == 1
                else expression("rem", window.rank(), literal(ring))
            )
            ordinal = expression("add", expression("mul", ordinal, literal(ring)), local)
        return CaseLease(
            case,
            1 if cross else width,
            ordinal,
            tuple(rings),
            tuple(uses[-1]) if uses else (Reuse(None, 0, 1, case.condition),),
            tuple(r for group in uses[:-1] for r in group),
            width if cross else None,
            policy,
        )

    def case(self, channel, case):
        """Preferred protocol: finite uses and native-boundary handbacks.

        Later queue-composition knowledge is an optional resource premise.
        It must not silently choose a narrower ring for an accepted preferred
        protocol. A failed whole case may require smaller earlier dimensions;
        retry once with queue-composition allowed throughout. The resource
        planner separately requests optional changes to accepted protocols.
        """
        d = self.domains
        d.work.ring_cases += 1
        cross = channel.mechanism is NotificationKind.CROSS_EVENT
        capacity = CROSS_BACKLOG if cross else LOCAL_CAPACITY
        proofs = {}

        def construct(modes):
            width, rings, uses = 1, [], []
            policy = "native-handback"
            for index in reversed(range(len(case.windows))):
                window = case.windows[index]
                for queue_composition in modes:
                    proof = None
                    for candidate in range(1, capacity // width + 1):
                        key = index, candidate, queue_composition
                        if key not in proofs:
                            proofs[key] = self._uses(
                                channel,
                                case,
                                window,
                                candidate,
                                reentry=index < len(case.windows) - 1,
                                queue_composition=queue_composition,
                            )
                        proof = proofs[key]
                        if proof is not None:
                            break
                    if proof is not None:
                        if queue_composition:
                            policy = "required-queue-handback"
                        break
                else:
                    return None
                width *= candidate
                rings.insert(0, (window, candidate))
                uses.insert(0, proof)
            return self._case_lease(case, rings, uses, cross=cross, policy=policy)

        preferred = construct((False, True))
        if preferred is not None:
            return preferred
        # A dimension's handback depends on its real endpoints and width,
        # never the other ring digits. Their independently smallest proved
        # widths minimize the product, without a Cartesian protocol search.
        required = construct((True,))
        if required is not None:
            return required
        d.fail(
            channel,
            "queue handback rule cannot establish consumption before reuse within event capacity",
            phase="notification-generation-lifetime",
            witness=tuple(
                f"optional relay {n.name}: {e.phase}"
                for n, e in self.declined_boundaries.items()
            ),
        )

    def smaller_lease(self, lease):
        """One finite, monotonically smaller option; no ring Cartesian product.

        Change a dimension only with its own complete handback. Unchanged
        dimensions retain their original facts, including outer reentry.
        Optional queue relays never insert or move an instruction.
        """
        channel, cases = lease.notification, []
        cross = channel.mechanism is NotificationKind.CROSS_EVENT
        for old in lease.cases:
            rings = list(old.rings)
            uses = [
                tuple(r for r in (*old.reentries, *old.inside) if r.loop is window.loop)
                for window, _ in rings
            ]
            for index in reversed(range(len(rings))):
                window, width = rings[index]
                for candidate in range(1, width):
                    proof = self._uses(
                        channel,
                        old.case,
                        window,
                        candidate,
                        reentry=index < len(rings) - 1,
                        queue_composition=True,
                    )
                    if proof is not None:
                        rings[index] = window, candidate
                        uses[index] = proof
                        break
            cases.append(
                old
                if tuple(rings) == old.rings
                else self._case_lease(old.case, rings, uses, cross=cross, policy="resource-shrink")
            )
        return StructuredEventLease(channel, max((c.width for c in cases), default=0), tuple(cases))

    def lease(self, notification):
        cases = tuple(
            self.case(notification, c)
            for c in self.domains.cases[notification]
            if self.domains.active[notification, c]
        )
        return StructuredEventLease(notification, max((c.width for c in cases), default=0), cases)
